/** localStorage key recording which regular round phrases have played at
 * least once (owner 2026-11-19: the weary Marvin lines join the rotation only
 * after every regular phrase was heard). Persisted like the other play-once
 * voice progress (Cypher background, first flags). */
export const AUTOPLAY_PHRASES_HEARD_KEY = 'wall-tones-autoplay-phrases-heard-v1';

function readHeardPhrases(): Set<string> {
  try {
    const raw = globalThis.localStorage?.getItem(AUTOPLAY_PHRASES_HEARD_KEY);
    if (raw == null) return new Set();
    const parsed: unknown = JSON.parse(raw);
    return new Set(Array.isArray(parsed) ? parsed.filter((x): x is string => typeof x === 'string') : []);
  } catch {
    return new Set();
  }
}

function writeHeardPhrases(heard: Set<string>): void {
  try {
    globalThis.localStorage?.setItem(AUTOPLAY_PHRASES_HEARD_KEY, JSON.stringify([...heard]));
  } catch {
    /* session may be private */
  }
}

let heardPhrases = readHeardPhrases();

/** Round-cue phrase rotation cursor (in-memory; resets with the page). */
let phraseCursor = 0;

/** Current round-cue rotation: the regular phrases, plus the weary Marvin
 * lines once every regular phrase has played at least once. */
function autoplayPhraseRotation(): readonly string[] {
  return heardPhrases.size >= AUTOPLAY_PHRASE_MP3_BASE64S.length
    ? [...AUTOPLAY_PHRASE_MP3_BASE64S, ...AUTOPLAY_MARVIN_MP3_BASE64S]
    : AUTOPLAY_PHRASE_MP3_BASE64S;
}

/** Next rotating round phrase; marks the picked regular phrase as heard. */
export function nextAutoplayPhraseBase64(): string {
  const rotation = autoplayPhraseRotation();
  const index = phraseCursor % rotation.length;
  phraseCursor += 1;
  const phrase = rotation[index]!;
  if (index < AUTOPLAY_PHRASE_MP3_BASE64S.length && !heardPhrases.has(String(index))) {
    heardPhrases.add(String(index));
    writeHeardPhrases(heardPhrases);
  }
  return phrase;
}

/** Test hook: restart the phrase rotation and forget heard phrases. */
export function resetAutoplayPhraseRotation(): void {
  phraseCursor = 0;
  heardPhrases = new Set();
  try {
    globalThis.localStorage?.removeItem(AUTOPLAY_PHRASES_HEARD_KEY);
  } catch {
    /* session may be private */
  }
}
